from datetime import datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read(d, name):
    p = os.path.join(d, name)
    if not os.path.exists(p):
        return []
    with open(p, encoding="utf-8-sig", newline="") as f:
        text = f.read()
    rows = []
    rd = csv.reader(io.StringIO(text))
    header = None
    for r in rd:
        if not r or all(not c.strip() for c in r):
            continue
        if header is None:
            header = [c.strip().lstrip("\ufeff") for c in r]
            continue
        rows.append({h: (r[i].strip() if i < len(r) else "") for i, h in enumerate(header)})
    return rows


def secs(t):
    h, m, s = t.strip().split(":")
    return int(h) * 3600 + int(m) * 60 + int(s)


def runs_on(date, cal, exc):
    # date: datetime.date; returns set-like predicate by service id
    ds = date.strftime("%Y%m%d")
    wd = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"][date.weekday()]

    def f(sid):
        e = exc.get((sid, ds))
        if e == "1":
            return True
        if e == "2":
            return False
        c = cal.get(sid)
        return bool(c and c["start_date"] <= ds <= c["end_date"] and c.get(wd) == "1")
    return f


def main(inp, out):
    with open(os.path.join(inp, "request.json"), encoding="utf-8") as f:
        dates = sorted(set(json.load(f)["service_dates"]))
    agencies = read(inp, "agency.txt")
    atz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    first_tz = agencies[0]["agency_timezone"] if agencies else "UTC"
    stops = {s["stop_id"]: s for s in read(inp, "stops.txt")}
    routes = {r["route_id"]: r for r in read(inp, "routes.txt")}
    trips = {t["trip_id"]: t for t in read(inp, "trips.txt")}
    cal = {c["service_id"]: c for c in read(inp, "calendar.txt")}
    exc = {(c["service_id"], c["date"]): c["exception_type"] for c in read(inp, "calendar_dates.txt")}
    freqs = {}
    for fr in read(inp, "frequencies.txt"):
        freqs.setdefault(fr["trip_id"], []).append(fr)
    st = {}
    for r in read(inp, "stop_times.txt"):
        st.setdefault(r["trip_id"], []).append(r)

    def is_board(s):
        lt = s.get("location_type", "")
        return lt == "1" or (lt in ("", "0") and not s.get("parent_station", ""))

    def board_of(sid):
        s = stops[sid]
        p = s.get("parent_station", "")
        return p if p and p in stops else sid

