            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        times = [secs(r["departure_time"] or r["arrival_time"]) if (r["departure_time"] or r["arrival_time"]) else None
                 for r in rows]
        known = [i for i, t in enumerate(times) if t is not None]
        for a, b in zip(known, known[1:]):
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // (b - a)
        trip = trips[tid]
        route = routes[trip["route_id"]]
        label = route.get("route_short_name", "") or route.get("route_long_name", "")
        last = stops[rows[-1]["stop_id"]]
        last = stops.get(last.get("parent_station", ""), last) if last.get("parent_station", "") else last
        deps = []
        for i, r in enumerate(rows[:-1]):
            if r.get("pickup_type", "") == "1":
                continue
            hs = r.get("stop_headsign", "") or trip.get("trip_headsign", "") or last["stop_name"]
            s = stops[r["stop_id"]]
            deps.append((i, board_of(r["stop_id"]), s.get("platform_code", "") or None, hs))
        prepared[tid] = (times, label, route["agency_id"], deps)

