                        if s0 >= e0:
                            continue
                        starts = list(range(s0, e0, h))
                        if w.get("exact_times", "") == "1":
                            items += [("scheduled", s + off, None, None) for s in starts]
                        else:
                            items.append(("interval", starts[0] + off, starts[-1] + off, h))
                else:
                    items.append(("scheduled", times[i], None, None))
                for kind, t, u, h in items:
                    entries.setdefault((b, ds), []).append((
                        origin + t, label, hs, tid, plat, kind,
                        None if u is None else origin + u, h, ag))
    for sid in sorted(boards):
        s = boards[sid]
        tzname = s.get("stop_timezone", "") or first_tz
        tz = ZoneInfo(tzname)

