            dt = datetime.fromtimestamp(x, timezone.utc).astimezone(tz)
            o = dt.utcoffset()
            tot = int(o.total_seconds())
            sign = "+" if tot >= 0 else "-"
            tot = abs(tot)
            return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, tot // 3600, tot % 3600 // 60)
        for ds in dates:
            es = entries.get((sid, ds), [])
            es.sort(key=lambda e: (e[0], e[1], e[2], e[3], e[4] is not None, e[4] or ""))
            result.append({
                "stop_id": sid, "name": s["stop_name"], "timezone": tzname, "service_date": ds,
                "departures": [{
                    "kind": e[5], "time": fmt(e[0]), "until": None if e[6] is None else fmt(e[6]),
                    "headway_secs": e[7], "route": e[1], "headsign": e[2], "trip": e[3],
                    "platform": e[4], "agency": e[8]} for e in es]})
    with open(out, "w", encoding="utf-8") as f:
        json.dump({"service_dates": dates, "boards": result}, f, ensure_ascii=False)


