        return lt == "1" or (lt in ("", "0") and not s.get("parent_station", ""))

    def board_of(sid):
        p = stops[sid].get("parent_station", "")
        return p if p and p in stops else sid

    prepared = {}
    for tid, rows in st.items():
        if tid not in trips:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        times = []
        for r in rows:
            t = r["departure_time"] or r["arrival_time"]
            times.append(secs(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for a, b in zip(known, known[1:]):
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // (b - a)
        trip = trips[tid]
        route = routes[trip["route_id"]]
        label = route.get("route_short_name", "") or route.get("route_long_name", "")
        last = stops[rows[-1]["stop_id"]]
        if last.get("parent_station", "") in stops:
            last = stops[last["parent_station"]]
        deps = []
        for i, r in enumerate(rows[:-1]):
            if r.get("pickup_type", "") == "1":
                continue
            hs = r.get("stop_headsign", "") or trip.get("trip_headsign", "") or last["stop_name"]
            s = stops[r["stop_id"]]
            deps.append((i, board_of(r["stop_id"]), s.get("platform_code", "") or None, hs))
        prepared[tid] = (times, label, route["agency_id"], deps)

    boards = {sid: s for sid, s in stops.items() if is_board(s)}
    entries = {}
    for ds in dates:
        d = datetime.strptime(ds, "%Y-%m-%d").date()
        runs = runs_on(d, cal, exc)
        for tid, (times, label, ag, deps) in prepared.items():
            trip = trips[tid]
            if not runs(trip["service_id"]):
                continue
            tz = ZoneInfo(atz[ag])
            noon = datetime(d.year, d.month, d.day, 12, tzinfo=tz).astimezone(timezone.utc)
            origin = int((noon - timedelta(hours=12)).timestamp())
            for (i, b, plat, hs) in deps:
                items = []
                if tid in freqs:
                    off = times[i] - times[0]
                    for w in freqs[tid]:
                        s0, e0, h = secs(w["start_time"]), secs(w["end_time"]), int(w["headway_secs"])
                        if s0 >= e0:
                            continue
                        starts = list(range(s0, e0, h))
                        if w.get("exact_times", "") == "1":
                            items += [("scheduled", s + off, None, None) for s in starts]
                        else:
                            items.append(("interval", starts[0] + off, starts[-1] + off, h))
                else:
                    items.append(("scheduled", times[i], None, None))
                for kind, t, u, h in items:
                    entries.setdefault((b, ds), []).append((
                        origin + t, label, hs, tid, plat, kind,
                        None if u is None else origin + u, h, ag))
    result = []
    for sid in sorted(boards):
        s = boards[sid]
        tzname = s.get("stop_timezone", "") or first_tz
        tz = ZoneInfo(tzname)

        def fmt(x):
            dt = datetime.fromtimestamp(x, timezone.utc).astimezone(tz)
            tot = int(dt.utcoffset().total_seconds())
            sign = "+" if tot >= 0 else "-"
            tot = abs(tot)
            return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, tot // 3600, tot % 3600 // 60)
        for ds in dates:
            es = entries.get((sid, ds), [])
            es.sort(key=lambda e: (e[0], e[1], e[2], e[3], e[4] is not None, e[4] or ""))
            result.append({
                "stop_id": sid, "name": s["stop_name"], "timezone": tzname, "service_date": ds,
                "departures": [{
                    "kind": e[5], "time": fmt(e[0]), "until": None if e[6] is None else fmt(e[6]),
                    "headway_secs": e[7], "route": e[1], "headsign": e[2], "trip": e[3],
                    "platform": e[4], "agency": e[8]} for e in es]})
    with open(out, "w", encoding="utf-8") as f:
        json.dump({"service_dates": dates, "boards": result}, f, ensure_ascii=False)


main(sys.argv[1], sys.argv[2])
